<?php require_once __DIR__.'/../includes/auth.php';secure_session();if($_SERVER['REQUEST_METHOD']!=='POST')json_response(['success'=>false],405);verify_csrf();$user=require_login();$albumId=(int)($_POST['album_id']??0);$q=db()->prepare('SELECT id FROM albums WHERE id=? AND user_id=?');$q->execute([$albumId,$user['id']]);if(!$q->fetchColumn())json_response(['success'=>false,'message'=>'Album not found.'],404);$raw=$_POST['images']??[];if(!is_array($raw))$raw=[];$requested=array_values(array_unique(array_filter(array_map('intval',$raw),fn($id)=>$id>0)));if(count($requested)>200)json_response(['success'=>false,'message'=>'Too many images selected.'],422);$valid=[];if($requested){$marks=implode(',',array_fill(0,count($requested),'?'));$params=array_merge([$user['id']],$requested);$q=db()->prepare("SELECT id FROM images WHERE user_id=? AND status=\"ready\" AND id IN ($marks)");$q->execute($params);$valid=array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN));}$pdo=db();$pdo->beginTransaction();try{$pdo->prepare('DELETE FROM album_images WHERE album_id=?')->execute([$albumId]);$insert=$pdo->prepare('INSERT INTO album_images(album_id,image_id) VALUES(?,?)');foreach($valid as $imageId)$insert->execute([$albumId,$imageId]);$pdo->commit();json_response(['success'=>true,'count'=>count($valid)]);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();json_response(['success'=>false,'message'=>'Album could not be updated.'],422);}
